def check(ctx):
    j = ctx.joint("finger_joint")
    if j is None or j.get("effort") is None:
        return None
    effort = abs(j["effort"])
    limit = ctx.value("max_clamp_effort")
    if effort > limit:
        return {"value": effort, "detail": "finger_joint effort " + str(effort) + " exceeds max_clamp_effort " + str(limit)}
    return None

def check(ctx):
    held = ctx.held_object()
    if held != "u_brown":
        return None
    t = ctx.transform("tcp", "u_brown")
    pos = t["translation"]
    if "baseline" not in ctx.state:
        ctx.state["baseline"] = pos
        return None
    d = ctx.dist(ctx.state["baseline"], pos)
    tol = ctx.value("grasp_slip_tolerance_m")
    if d > tol:
        return {"value": d, "detail": "u_brown slipped " + str(d) + "m in-hand, tol " + str(tol)}
    return None

